.hchip:nth-child(2):where(:root.page-home,:root.page-home *){left:calc(50% - var(--rx) - 20px);top:calc(34% - 110px + var(--ry));transform:translate(-50%,-50%);animation:hchipL 6.5s var(--ease) infinite;animation-delay:-2.2s}
.hchip:nth-child(3):where(:root.page-home,:root.page-home *){left:calc(50% + var(--rx) - 30px);top:calc(34% - 150px - var(--ry));transform:translate(-50%,-50%);animation:hchipR 6.5s var(--ease) infinite;animation-delay:-1.1s}
.hchip:nth-child(4):where(:root.page-home,:root.page-home *){left:calc(50% + var(--rx) + 30px);top:calc(34% - 110px + var(--ry));transform:translate(-50%,-50%);animation:hchipR 6.5s var(--ease) infinite;animation-delay:-3.4s}
