.hchip:where(:root.page-home,:root.page-home *)::before{content:"";position:absolute;inset:0;border-radius:26px;padding:1.4px;pointer-events:none; background:linear-gradient(180deg,rgba(255,255,255,.85),rgba(255,255,255,.05) 70%,transparent); -webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude}
