.hchip:nth-child(3):where(:root.page-integrations,:root.page-integrations *){left:calc(50% + var(--rx) - 30px);top:calc(34% - 150px - var(--ry));transform:translate(-50%,-50%);animation:hchipR 6.5s var(--ease) infinite;animation-delay:-1.1s}
