.vplace-top:where(:root.page-videos,:root.page-videos *){display:flex;align-items:center;justify-content:space-between;padding:11px 14px;border-bottom:1px solid var(--line-2)}
.vplace-top .vt:where(:root.page-videos,:root.page-videos *){font-weight:600;font-size:13.5px}
.vplace-top .vmeta:where(:root.page-videos,:root.page-videos *){font-family:var(--font-mono);font-size:10px;letter-spacing:.06em;color:var(--ink-3)}
.poster:where(:root.page-videos,:root.page-videos *){position:relative;flex:1;overflow:hidden;background: radial-gradient(120% 120% at 80% 0%, var(--paper-2), var(--paper))}
.poster-dots:where(:root.page-videos,:root.page-videos *){position:absolute;inset:0;background-image:radial-gradient(var(--hair) 1px,transparent 1px);background-size:18px 18px;opacity:.6;-webkit-mask-image:linear-gradient(transparent,#000 30%);mask-image:linear-gradient(transparent,#000 30%)}
.play:where(:root.page-videos,:root.page-videos *){position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:3; width:64px;height:64px;border-radius:50%;background:var(--wine);border:0; display:grid;place-items:center;box-shadow:0 16px 40px -12px rgba(155,27,46,.6);transition:.25s var(--ease)}
.play:where(:root.page-videos,:root.page-videos *)::after{content:"";width:0;height:0;border-left:17px solid #fff;border-top:11px solid transparent;border-bottom:11px solid transparent;margin-left:4px}
.play:hover:where(:root.page-videos,:root.page-videos *){transform:translate(-50%,-50%) scale(1.07)}
.play-ring:where(:root.page-videos,:root.page-videos *){position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:64px;height:64px;border-radius:50%;border:1px solid var(--wine-line);z-index:2;animation:ring 3s var(--ease) infinite}
.vcap:where(:root.page-videos,:root.page-videos *){position:absolute;left:14px;bottom:13px;z-index:3;font-family:var(--font-mono);font-size:10px;letter-spacing:.06em;color:var(--ink-3);background:rgba(255,255,255,.7);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);padding:5px 9px;border-radius:6px;border:1px solid var(--line)}

/* faux dashboard rows inside poster */
.fx:where(:root.page-videos,:root.page-videos *){position:absolute;border-radius:7px;background:var(--paper);border:1px solid var(--line);box-shadow:var(--shadow-sm)}
.fx-row:where(:root.page-videos,:root.page-videos *){display:flex;align-items:center;gap:9px;padding:9px 12px}
.fx-ic:where(:root.page-videos,:root.page-videos *){width:24px;height:24px;border-radius:6px;background:var(--accent-soft);flex:none}
.fx-bar:where(:root.page-videos,:root.page-videos *){height:7px;border-radius:4px;background:var(--paper-3)}
.fx-chip:where(:root.page-videos,:root.page-videos *){font-family:var(--font-mono);font-size:9px;letter-spacing:.05em;color:var(--ink-3);border:1px solid var(--line);border-radius:5px;padding:2px 6px}
.fx-col:where(:root.page-videos,:root.page-videos *){display:flex;flex-direction:column;justify-content:flex-end;gap:0;align-items:center}
.fx-colbar:where(:root.page-videos,:root.page-videos *){width:18px;border-radius:3px 3px 0 0;background:var(--accent);opacity:.85}
