.fx-colbar.wine:where(:root.page-videos,:root.page-videos *){background:var(--wine)}

/* floating controls */
.stage-ctrl:where(:root.page-videos,:root.page-videos *){position:absolute;right:16px;bottom:16px;z-index:6;display:flex;align-items:center;gap:7px;background:rgba(255,255,255,.86);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);border:1px solid var(--line);border-radius:100px;padding:6px;box-shadow:var(--shadow-md)}
.stage-ctrl button:where(:root.page-videos,:root.page-videos *){width:30px;height:30px;border-radius:50%;border:1px solid transparent;background:transparent;color:var(--ink-2);display:grid;place-items:center;transition:.18s}
