.dots:where(:root.page-videos,:root.page-videos *){display:flex;gap:6px;padding:0 4px}
.dots i:where(:root.page-videos,:root.page-videos *){width:6px;height:6px;border-radius:50%;background:var(--line);transition:.25s;cursor:pointer}
.dots i.on:where(:root.page-videos,:root.page-videos *){background:var(--wine);width:18px;border-radius:4px}

/* ============================ TRUST BAR (left text · right logo cloud) ============================ */
.trustbar:where(:root.page-videos,:root.page-videos *){background:var(--paper);padding-block:clamp(24px,3vw,40px)}
.trustbar-in:where(:root.page-videos,:root.page-videos *){display:grid;grid-template-columns:minmax(180px,0.66fr) 1.7fr;gap:clamp(20px,3.2vw,48px);align-items:center}
.trustbar-label:where(:root.page-videos,:root.page-videos *){font-size:clamp(18px,1.95vw,24px);font-weight:600;letter-spacing:-0.01em;color:var(--ink);line-height:1.3;display:block;max-width:22ch}
.tb-marquee:where(:root.page-videos,:root.page-videos *){position:relative;overflow:hidden; -webkit-mask-image:linear-gradient(90deg,transparent,#000 7%,#000 93%,transparent); mask-image:linear-gradient(90deg,transparent,#000 7%,#000 93%,transparent)}
.tb-track:where(:root.page-videos,:root.page-videos *){display:flex;align-items:center;width:max-content;gap:clamp(34px,3.8vw,60px);animation:tbScroll 36s linear infinite}
.tb-marquee:hover .tb-track:where(:root.page-videos,:root.page-videos *){animation-play-state:paused}
