.tb-logo:where(:root.page-videos,:root.page-videos *){display:inline-flex;align-items:center;gap:8px;font-weight:700;font-size:clamp(18px,1.8vw,23px);letter-spacing:-0.02em;color:var(--ink-3);opacity:.7;white-space:nowrap;transition:color .22s var(--ease),opacity .22s var(--ease)}
.tb-logo:hover:where(:root.page-videos,:root.page-videos *){color:var(--ink);opacity:1}
.tb-ic:where(:root.page-videos,:root.page-videos *){width:.92em;height:.92em;fill:currentColor;flex:none}
.tb-sap:where(:root.page-videos,:root.page-videos *){font-weight:800;letter-spacing:.01em}
.tb-aws:where(:root.page-videos,:root.page-videos *){font-weight:800;letter-spacing:-.03em;align-items:flex-end;gap:2px}
.tb-aws .tb-smile:where(:root.page-videos,:root.page-videos *){width:1.5em;height:.4em;fill:currentColor;margin-bottom:3px}

/* ============================ MILESTONE JOURNEY ============================ */
.journey:where(:root.page-videos,:root.page-videos *){position:relative;--jpt:clamp(57px,6.6vw,92px);padding-block:var(--jpt) 0}
.journey:where(:root.page-videos,:root.page-videos *)::before{content:"";position:absolute;top:0;left:0;right:0;height:1px;z-index:0;pointer-events:none; background:repeating-linear-gradient(90deg,var(--hair) 0 7px,transparent 7px 15px);background-size:15px 1px;animation:dashFlowX 1.1s linear infinite}
html[data-motion="off"] .journey:where(:root.page-videos,:root.page-videos *)::before{animation:none}
.journey-head:where(:root.page-videos,:root.page-videos *){text-align:center;max-width:640px;margin:0 auto clamp(52px,6vw,86px)}
.journey-head .eyebrow:where(:root.page-videos,:root.page-videos *){margin-bottom:18px}
.journey-head .h-section:where(:root.page-videos,:root.page-videos *){margin:0 auto}
.journey>.wrap:where(:root.page-videos,:root.page-videos *){position:relative}
.journey>.wrap:where(:root.page-videos,:root.page-videos *)::before,.journey>.wrap:where(:root.page-videos,:root.page-videos *)::after{content:"";position:absolute;top:calc(var(--jpt)*-1);bottom:0;width:1px;z-index:0;pointer-events:none; background:repeating-linear-gradient(180deg,var(--hair) 0 6px,transparent 6px 13px);background-size:1px 13px;animation:dashFlowY 1.1s linear infinite}
.journey>.wrap:where(:root.page-videos,:root.page-videos *)::before{left:0}
.journey>.wrap:where(:root.page-videos,:root.page-videos *)::after{right:0}
html[data-motion="off"] .journey>.wrap:where(:root.page-videos,:root.page-videos *)::before,html[data-motion="off"] .journey>.wrap:where(:root.page-videos,:root.page-videos *)::after{animation:none}
.journey-map:where(:root.page-videos,:root.page-videos *){position:relative}
.journey-curve:where(:root.page-videos,:root.page-videos *){position:absolute;top:0;left:0;width:100%;height:196px;z-index:0;overflow:visible; -webkit-mask-image:linear-gradient(90deg,transparent,#000 3%,#000 100%); mask-image:linear-gradient(90deg,transparent,#000 3%,#000 100%)}
.jc-base:where(:root.page-videos,:root.page-videos *){fill:none;stroke:#d8d5ce;stroke-width:2;vector-effect:non-scaling-stroke;stroke-linecap:round}
.jc-line:where(:root.page-videos,:root.page-videos *){fill:none;stroke:var(--wine);stroke-width:2;vector-effect:non-scaling-stroke;stroke-linecap:round}
.journey-row:where(:root.page-videos,:root.page-videos *){position:relative;z-index:1;display:grid;grid-template-columns:repeat(5,1fr)}
.milestone:where(:root.page-videos,:root.page-videos *){display:flex;flex-direction:column;align-items:center;text-align:center;padding-inline:clamp(6px,1vw,16px)}
.milestone .dot:where(:root.page-videos,:root.page-videos *){width:14px;height:14px;border-radius:50%;background:var(--paper);border:2px solid #cbc8c1; margin-top:calc(var(--cy) - 7px);position:relative;z-index:2;box-shadow:0 0 0 5px rgba(20,16,22,.03);transition:border-color .25s var(--ease),box-shadow .25s var(--ease)}
.milestone .dot:where(:root.page-videos,:root.page-videos *)::after{content:"";position:absolute;top:50%;left:50%;width:8px;height:8px;margin:-4px 0 0 -4px;border-radius:50%;background:var(--wine);transform:scale(0)}
.milestone .dot.lit:where(:root.page-videos,:root.page-videos *)::after{animation:dotPop .46s cubic-bezier(.34,1.56,.64,1) forwards}
html[data-motion="off"] .milestone .dot.lit:where(:root.page-videos,:root.page-videos *)::after{animation:none;transform:scale(1)}
.milestone .dot.lit:where(:root.page-videos,:root.page-videos *){border-color:var(--wine);box-shadow:0 0 0 5px color-mix(in srgb,var(--wine) 9%,transparent)}
.milestone .conn:where(:root.page-videos,:root.page-videos *){width:1px;height:200px; background:linear-gradient(180deg,var(--wine) calc(var(--fill,0)*100%),#d8d5ce calc(var(--fill,0)*100%))}
.milestone .mcontent:where(:root.page-videos,:root.page-videos *){margin-top:18px;padding-bottom:clamp(40px,5.5vw,84px)}

/* centered trust badges (top open space, above the arc) */
.journey-badges:where(:root.page-videos,:root.page-videos *){position:relative;z-index:3;display:inline-flex;gap:0;justify-content:center;margin:0 auto; background:linear-gradient(135deg,var(--wine-soft) 0%,#fff 45%,var(--accent-soft) 100%); border:1px solid var(--wine-line);border-radius:100px;padding:6px;box-shadow:0 18px 40px -22px rgba(120,18,28,.3)}
.journey-badges-wrap:where(:root.page-videos,:root.page-videos *){display:flex;justify-content:center;margin-bottom:clamp(16px,2vw,28px)}
.journey-badges .jb:where(:root.page-videos,:root.page-videos *){display:flex;align-items:center;gap:11px;padding:10px 24px;position:relative}
.journey-badges .jb+.jb:where(:root.page-videos,:root.page-videos *)::before{content:"";position:absolute;left:0;top:50%;transform:translateY(-50%);width:1px;height:26px;background:var(--wine-line)}
.journey-badges .jb-ic:where(:root.page-videos,:root.page-videos *){width:24px;height:24px;border-radius:50%;background:var(--wine-soft);color:var(--wine);display:grid;place-items:center;font-size:12px;font-weight:700;flex:none}
.journey-badges .jb-t b:where(:root.page-videos,:root.page-videos *){font-size:14px;font-weight:700;letter-spacing:-0.01em;display:block;line-height:1.05}
.journey-badges .jb-t span:where(:root.page-videos,:root.page-videos *){font-family:var(--font-mono);font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3)}
.mcontent .mnum:where(:root.page-videos,:root.page-videos *){font-size:clamp(30px,3.4vw,50px);font-weight:700;letter-spacing:-0.03em;line-height:1;color:var(--ink);font-variant-numeric:tabular-nums}
.mcontent .mlbl:where(:root.page-videos,:root.page-videos *){font-family:var(--font-mono);font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--ink-3);margin-top:11px}

/* ============================ PRODUCT EXPLORER ============================ */
.prodx:where(:root.page-videos,:root.page-videos *){padding-block:clamp(76px,9.5vw,140px);background:#F3F1EE}
.prodx-head:where(:root.page-videos,:root.page-videos *){text-align:center;margin-bottom:clamp(26px,3.2vw,44px)}
.prodx-head .h-section:where(:root.page-videos,:root.page-videos *){margin:0 auto;max-width:none;font-size:clamp(24px,3.4vw,42px)}
.prodx-card:where(:root.page-videos,:root.page-videos *){background:var(--paper);border-radius:28px;padding:clamp(22px,2.8vw,42px)}
.prodx-tabs:where(:root.page-videos,:root.page-videos *){position:relative;display:flex;flex-wrap:nowrap;gap:clamp(8px,2vw,40px);margin-bottom:clamp(26px,3.2vw,44px)}
.prodx-ind:where(:root.page-videos,:root.page-videos *){position:absolute;top:0;left:0;height:100%;width:0;border-radius:20px 20px 2px 2px;background:var(--wine-soft);z-index:0;pointer-events:none}
.prodx-tab:where(:root.page-videos,:root.page-videos *){position:relative;z-index:1;flex:1 1 0;min-width:0;text-align:center;font-size:clamp(15px,1.95vw,31px);font-weight:400;letter-spacing:-0.025em;line-height:1;color:#b7adb0;background:transparent;border:0;padding:clamp(16px,1.8vw,26px) 10px;border-radius:20px 20px 2px 2px;cursor:pointer;transition:color .2s var(--ease),background .2s var(--ease)}
.prodx-tab:hover:where(:root.page-videos,:root.page-videos *){color:var(--wine)}
.prodx-tab:not(.is-active):hover:where(:root.page-videos,:root.page-videos *){background:color-mix(in srgb,var(--wine) 6%,transparent)}
.prodx-tab.is-active:where(:root.page-videos,:root.page-videos *){color:var(--wine);font-weight:700}
.prodx-stage:where(:root.page-videos,:root.page-videos *){display:grid;grid-template-columns:0.82fr 1.18fr;gap:clamp(26px,3.4vw,52px);align-items:center;background:none;border:0;box-shadow:none;padding:0;border-radius:0}
.prodx-info:where(:root.page-videos,:root.page-videos *){min-width:0;padding-left:clamp(2px,1.2vw,20px)}
.pi-title:where(:root.page-videos,:root.page-videos *){font-size:clamp(26px,3vw,42px);font-weight:700;letter-spacing:-0.03em;line-height:1.04;margin:0 0 16px;text-wrap:balance}
.pi-desc:where(:root.page-videos,:root.page-videos *){font-size:16px;color:var(--ink-2);line-height:1.6;max-width:42ch}
.pi-link:where(:root.page-videos,:root.page-videos *){margin-top:26px}
.pi-link.link-arrow:where(:root.page-videos,:root.page-videos *){color:var(--wine);border-bottom:0;padding:10px 18px;border-radius:100px;background:transparent;border:1px solid var(--wine-line);transition:background .22s var(--ease),border-color .22s var(--ease),color .22s}
.pi-link.link-arrow:hover:where(:root.page-videos,:root.page-videos *){background:var(--wine-soft);border-color:var(--wine)}
.pi-link.link-arrow .arr:where(:root.page-videos,:root.page-videos *){color:var(--wine)}
.prodx-viz:where(:root.page-videos,:root.page-videos *){position:relative;min-height:360px;border-radius:20px;overflow:visible;padding:0;display:flex;align-items:center;justify-content:center;background:transparent}
.prodx-figstack:where(:root.page-videos,:root.page-videos *){position:relative;width:100%;aspect-ratio:1536/1024}
.prodx-fig:where(:root.page-videos,:root.page-videos *){position:absolute;inset:0;width:100%;height:100%;object-fit:contain;opacity:0;transform:scale(.985);transition:opacity .5s var(--ease),transform .6s var(--ease);pointer-events:none}
.prodx-fig.is-active:where(:root.page-videos,:root.page-videos *){opacity:1;transform:none}
.prodx-vidframe:where(:root.page-videos,:root.page-videos *){width:100%;border-radius:18px;overflow:hidden;border:1px solid var(--line);background:var(--paper);box-shadow:var(--shadow-lg)}
.pvf-bar:where(:root.page-videos,:root.page-videos *){display:flex;align-items:center;gap:12px;padding:11px 16px;background:var(--paper-2);border-bottom:1px solid var(--line-2)}
.pvf-dots:where(:root.page-videos,:root.page-videos *){display:flex;gap:6px}
.pvf-dots i:where(:root.page-videos,:root.page-videos *){width:10px;height:10px;border-radius:50%;background:#d8d5ce;display:block}
.pvf-url:where(:root.page-videos,:root.page-videos *){font-family:var(--font-mono);font-size:11px;color:var(--ink-3);background:var(--paper);border:1px solid var(--line);border-radius:7px;padding:4px 12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pvf-screen:where(:root.page-videos,:root.page-videos *){position:relative;aspect-ratio:16/10;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;background: radial-gradient(120% 120% at 50% 0%, var(--paper-2), var(--paper));overflow:hidden}
.pvf-screen:where(:root.page-videos,:root.page-videos *)::before{content:"";position:absolute;inset:0;background-image:radial-gradient(var(--hair) 1.1px,transparent 1.1px);background-size:22px 22px;opacity:.5;-webkit-mask-image:radial-gradient(circle at 50% 42%,#000,transparent 70%);mask-image:radial-gradient(circle at 50% 42%,#000,transparent 70%)}
.pvf-play:where(:root.page-videos,:root.page-videos *){position:relative;z-index:1;width:66px;height:66px;border-radius:50%;background:var(--wine);box-shadow:0 16px 40px -12px rgba(155,27,46,.6);display:grid;place-items:center}
.pvf-play:where(:root.page-videos,:root.page-videos *)::after{content:"";width:0;height:0;border-left:18px solid #fff;border-top:12px solid transparent;border-bottom:12px solid transparent;margin-left:5px}
.pvf-cap:where(:root.page-videos,:root.page-videos *){position:relative;z-index:1;font-family:var(--font-mono);font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3)}
.prodx-viz:where(:root.page-videos,:root.page-videos *)::before{content:none}
.viz-panel:where(:root.page-videos,:root.page-videos *){position:absolute;inset:clamp(20px,2.4vw,34px);opacity:0;visibility:hidden;align-items:center}
.viz-panel.is-active:where(:root.page-videos,:root.page-videos *){position:relative;inset:auto;width:100%;opacity:1;visibility:visible;display:flex}
.vframe:where(:root.page-videos,:root.page-videos *){width:100%}
.vmedia:where(:root.page-videos,:root.page-videos *){position:relative;aspect-ratio:16/9;background:var(--ink);overflow:hidden}
.prodx-vid:where(:root.page-videos,:root.page-videos *){position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}
.prodx-shot:where(:root.page-videos,:root.page-videos *){position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:top left;display:block}
.pv-float:where(:root.page-videos,:root.page-videos *){position:absolute;z-index:4;display:flex;align-items:center;gap:10px;background:rgba(255,255,255,.95);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);border:1px solid rgba(255,255,255,.8);border-radius:13px;padding:11px 14px;box-shadow:0 18px 40px -20px rgba(40,8,16,.5)}
.pv-f1:where(:root.page-videos,:root.page-videos *){left:-16px;top:20%;animation:floatCard 6.5s var(--ease) infinite}
.pv-f2:where(:root.page-videos,:root.page-videos *){right:-14px;bottom:15%;flex-direction:column;align-items:flex-start;gap:2px;animation:floatCard 7.5s var(--ease) infinite reverse}
.pv-check:where(:root.page-videos,:root.page-videos *){width:28px;height:28px;border-radius:50%;background:var(--wine-soft);color:var(--wine);display:grid;place-items:center;font-weight:700;font-size:13px;flex:none}
.pv-tx b:where(:root.page-videos,:root.page-videos *),.pv-big:where(:root.page-videos,:root.page-videos *){font-size:13px;font-weight:700;color:var(--ink);letter-spacing:-0.01em;display:block}
.pv-big:where(:root.page-videos,:root.page-videos *){font-size:21px}
.pv-tx span:where(:root.page-videos,:root.page-videos *),.pv-f2 span:where(:root.page-videos,:root.page-videos *){font-size:11px;color:var(--ink-3)}
.vframe:where(:root.page-videos,:root.page-videos *){border:1px solid var(--line);border-radius:16px;overflow:hidden;background:var(--paper-2);box-shadow:var(--shadow-sm)}
.vbar:where(:root.page-videos,:root.page-videos *){display:flex;align-items:center;gap:12px;padding:11px 14px;background:var(--paper);border-bottom:1px solid var(--line-2)}
