.sig-accent path:where(:root.page-brochures,:root.page-brochures *){fill:none;stroke:var(--wine);stroke-width:3;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke;opacity:.5}
.sig-ink:where(:root.page-brochures,:root.page-brochures *){fill:none;stroke:var(--wine);stroke-width:5;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 2px 6px rgba(155,27,46,.28))}
.sig-pegs:where(:root.page-brochures,:root.page-brochures *){position:absolute;inset:0;z-index:2;pointer-events:none}
.sig-peg:where(:root.page-brochures,:root.page-brochures *){position:absolute;width:13px;height:13px;margin:-6.5px 0 0 -6.5px;border-radius:50%;background:#fff;border:2px solid #D8D4CD;box-shadow:0 4px 10px -3px rgba(40,20,26,.3);transition:.35s var(--ease)}
.sig-peg.lit:where(:root.page-brochures,:root.page-brochures *){border-color:var(--wine);background:var(--wine);box-shadow:0 0 0 4px rgba(155,27,46,.16),0 6px 14px -4px rgba(155,27,46,.5)}
.sig-stem:where(:root.page-brochures,:root.page-brochures *){position:absolute;width:1.6px;margin-left:-0.8px;background:linear-gradient(var(--wine),rgba(155,27,46,.12));transform-origin:top;z-index:2;opacity:.35;transition:opacity .35s var(--ease)}
.sig-stem.lit:where(:root.page-brochures,:root.page-brochures *){opacity:1}
.loopx-steps:where(:root.page-brochures,:root.page-brochures *){position:absolute;inset:0;z-index:3}
.lxstep:where(:root.page-brochures,:root.page-brochures *){position:absolute;display:flex;flex-direction:column;align-items:flex-start;gap:6px;width:clamp(126px,12vw,156px);text-align:left; background:var(--paper);border:1px solid var(--line);border-radius:14px;padding:11px 13px;box-shadow:0 12px 28px -14px rgba(40,20,26,.26);transition:border-color .35s var(--ease),box-shadow .35s var(--ease),background .35s}
.lxstep.above:where(:root.page-brochures,:root.page-brochures *){transform:translate(-50%,calc(-100% - 13px))}
.lxstep.below:where(:root.page-brochures,:root.page-brochures *){transform:translate(-50%,13px)}
.lxstep .lxs-dot:where(:root.page-brochures,:root.page-brochures *){width:22px;height:22px;border-radius:7px;background:var(--paper-2);border:1.5px solid var(--line);display:grid;place-items:center;transition:.35s var(--ease);flex:none;position:relative}
.lxstep .lxs-dot:where(:root.page-brochures,:root.page-brochures *)::after{content:"";width:7px;height:4px;border-left:2px solid var(--ink-3);border-bottom:2px solid var(--ink-3);transform:rotate(-45deg) translateY(-1px);transition:.35s}
.lxstep b:where(:root.page-brochures,:root.page-brochures *){font-size:13px;font-weight:700;letter-spacing:-0.01em;color:var(--ink);transition:color .35s;line-height:1.12}
.lxstep .lxs-sub:where(:root.page-brochures,:root.page-brochures *){font-size:10.5px;line-height:1.32;color:var(--ink-3);transition:color .35s;text-wrap:pretty}
.lxstep.lit:where(:root.page-brochures,:root.page-brochures *){border-color:var(--wine);box-shadow:0 16px 34px -12px rgba(155,27,46,.4);z-index:6}
.lxstep.lit .lxs-dot:where(:root.page-brochures,:root.page-brochures *){border-color:var(--wine);background:var(--wine)}
.lxstep.lit .lxs-dot:where(:root.page-brochures,:root.page-brochures *)::after{border-color:#fff}
.lxstep.lit .lxs-sub:where(:root.page-brochures,:root.page-brochures *){color:var(--ink-2)}
.loopx-comet:where(:root.page-brochures,:root.page-brochures *){position:absolute;left:0;top:0;width:16px;height:16px;margin:-8px 0 0 -8px;border-radius:50%;z-index:5; background:radial-gradient(circle,#fff 0%,var(--wine) 55%,rgba(155,27,46,0) 72%); box-shadow:0 0 16px 4px rgba(155,27,46,.7),0 0 5px 1px #fff;pointer-events:none}

/* ============================ INDUSTRY FIT ============================ */
.ind-head:where(:root.page-brochures,:root.page-brochures *){display:grid;grid-template-columns:1fr 1fr;gap:30px;align-items:end;margin-bottom:48px}
