.ind-more:where(:root.page-brochures,:root.page-brochures *){flex:none;white-space:nowrap;font-size:14px;font-weight:600;color:var(--wine);padding:11px 22px;border:1px solid var(--wine);border-radius:100px;background:var(--wine-soft);cursor:pointer;display:inline-flex;align-items:center;gap:8px;transition:.2s var(--ease)}
transition:.2s var(--ease)} .ind-more:hover:where(:root.page-brochures,:root.page-brochures *){background:var(--wine);color:#fff}
.ind-more .im-ic:where(:root.page-brochures,:root.page-brochures *){font-size:10px;transition:transform .25s var(--ease)}
