.ind-all-close:where(:root.page-brochures,:root.page-brochures *){width:32px;height:32px;border-radius:50%;border:1px solid var(--line);background:var(--paper);color:var(--ink);cursor:pointer;font-size:13px;transition:.2s}
.ind-all-close:hover:where(:root.page-brochures,:root.page-brochures *){border-color:var(--ink);background:var(--paper-2)}
.ind-allgrid:where(:root.page-brochures,:root.page-brochures *){display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.ind-allgrid button:where(:root.page-brochures,:root.page-brochures *){text-align:left;font-size:14px;font-weight:600;color:var(--ink-2);padding:13px 16px;border:1px dashed var(--line);border-radius:12px;background:transparent;cursor:pointer;transition:.18s var(--ease)}
.ind-allgrid button:hover:where(:root.page-brochures,:root.page-brochures *){color:var(--wine);border-color:var(--wine-line);background:var(--wine-soft)}
.ind-allgrid button.is-active:where(:root.page-brochures,:root.page-brochures *){color:var(--wine);border-style:solid;border-color:var(--wine);background:var(--wine-soft)}
.ind-tab:where(:root.page-brochures,:root.page-brochures *){flex:none;white-space:nowrap;font-size:14px;font-weight:600;color:#9a9098;padding:9px 18px;border:1px dashed #c7bcc0;border-radius:100px;background:transparent;cursor:pointer;transition:color .2s,border-color .2s,background .2s}
.ind-panel:where(:root.page-brochures,:root.page-brochures *){display:grid;grid-template-columns:1fr 1.05fr;gap:clamp(24px,3vw,48px);align-items:stretch; border:1px solid var(--line);border-radius:24px;background:var(--paper);padding:clamp(18px,1.8vw,26px);min-height:400px}
