.ind-media img:where(:root.page-brochures,:root.page-brochures *){width:100%;height:100%;object-fit:cover;display:block}
.ind-content:where(:root.page-brochures,:root.page-brochures *){display:flex;flex-direction:column;padding:clamp(8px,1vw,16px) clamp(8px,1.4vw,22px) clamp(8px,1vw,16px) 0}
.ind-toprow:where(:root.page-brochures,:root.page-brochures *){display:flex;align-items:center;justify-content:space-between;gap:16px}
.ind-brand:where(:root.page-brochures,:root.page-brochures *){display:flex;align-items:center;gap:12px}
.ind-glyph:where(:root.page-brochures,:root.page-brochures *){width:38px;height:38px;border-radius:10px;background:var(--wine);color:#fff;display:grid;place-items:center;font-weight:700;font-size:16px;flex:none}
