.ind-counter:where(:root.page-brochures,:root.page-brochures *){font-family:var(--font-mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--ink-3);display:inline-flex;align-items:center;gap:10px;white-space:nowrap}
