.ind-sub:where(:root.page-brochures,:root.page-brochures *){font-size:13px;font-weight:500;color:var(--ink-3);margin-top:14px;letter-spacing:-0.005em}
.ind-learn:where(:root.page-brochures,:root.page-brochures *){margin-top:auto;align-self:flex-start;display:inline-flex;align-items:center;gap:9px;font-weight:600;font-size:15px;color:var(--wine);width:fit-content;padding:10px 18px;border-radius:100px;background:transparent;border:1px solid var(--wine-line);transition:background .22s var(--ease),border-color .22s var(--ease),color .22s}
