.ind-rep-img:where(:root.page-brochures,:root.page-brochures *){width:60px;height:60px;border-radius:12px;object-fit:cover;flex:none;background:var(--paper-3)}
.ind-rep-t b:where(:root.page-brochures,:root.page-brochures *){font-size:15px;font-weight:700;letter-spacing:-0.01em;display:block;color:var(--ink)}
.ind-rep-t span:where(:root.page-brochures,:root.page-brochures *){font-size:12.5px;color:var(--ink-3);margin-top:2px;display:block}

