.why-d:where(:root.page-brochures,:root.page-brochures *){grid-area:d}
.why-card:where(:root.page-brochures,:root.page-brochures *){position:relative;border:1px solid var(--line);border-radius:20px;padding:clamp(24px,2.3vw,34px);background:var(--paper);display:flex;flex-direction:column;transition:transform .25s var(--ease),box-shadow .25s var(--ease),border-color .25s}
.why-card:hover:where(:root.page-brochures,:root.page-brochures *){transform:translateY(-3px);box-shadow:var(--shadow-md);border-color:var(--ink)}
.why-icon:where(:root.page-brochures,:root.page-brochures *){width:48px;height:48px;border-radius:13px;background:var(--wine-soft);color:var(--wine);display:grid;place-items:center;flex:none;margin-bottom:22px}
.why-card h3:where(:root.page-brochures,:root.page-brochures *){font-size:clamp(19px,2vw,24px);font-weight:700;letter-spacing:-0.02em;margin-bottom:12px}
