/* feature card */
.why-feat:where(:root.page-brochures,:root.page-brochures *){background:linear-gradient(158deg,#B23a4a 0%,#8E1B2C 52%,#67121F 100%);border-color:transparent;color:#fff;justify-content:space-between;overflow:hidden}
.why-feat:where(:root.page-brochures,:root.page-brochures *)::after{content:"";position:absolute;right:-60px;top:-60px;width:240px;height:240px;border-radius:50%;border:1.5px dashed rgba(255,255,255,.26);pointer-events:none;animation:spinCW 26s linear infinite}
.why-feat:where(:root.page-brochures,:root.page-brochures *)::before{content:"";position:absolute;right:-110px;top:-110px;width:340px;height:340px;border-radius:50%;border:1.5px dashed rgba(255,255,255,.16);pointer-events:none;animation:spinCCW 34s linear infinite}
html[data-motion="off"] .why-feat:where(:root.page-brochures,:root.page-brochures *)::before,html[data-motion="off"] .why-feat:where(:root.page-brochures,:root.page-brochures *)::after{animation:none}
.wf-top:where(:root.page-brochures,:root.page-brochures *){display:flex;align-items:flex-start;justify-content:space-between;position:relative;z-index:1}
.wf-kick:where(:root.page-brochures,:root.page-brochures *){margin-top:10px}
.why-icon.wi-light:where(:root.page-brochures,:root.page-brochures *){background:rgba(255,255,255,.16);color:#fff;margin-bottom:0}
.wf-kick:where(:root.page-brochures,:root.page-brochures *){font-family:var(--font-mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,.7)}
.wf-body:where(:root.page-brochures,:root.page-brochures *){position:relative;z-index:1;margin-top:auto;padding-top:40px}
.wf-num:where(:root.page-brochures,:root.page-brochures *){font-size:clamp(48px,5.4vw,76px);font-weight:700;letter-spacing:-0.04em;line-height:.9}
.wf-num span:where(:root.page-brochures,:root.page-brochures *){font-size:.32em;font-weight:600;letter-spacing:-0.01em;color:rgba(255,255,255,.7)}
.why-feat h3:where(:root.page-brochures,:root.page-brochures *){margin:18px 0 12px;font-size:clamp(22px,2.2vw,27px)}
