.why-d-stat b:where(:root.page-brochures,:root.page-brochures *){font-size:clamp(34px,3.6vw,52px);font-weight:700;letter-spacing:-0.03em;color:var(--wine);line-height:1;display:block}
.why-d-stat span:where(:root.page-brochures,:root.page-brochures *){font-family:var(--font-mono);font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3);margin-top:6px;display:block}
.why-d p:where(:root.page-brochures,:root.page-brochures *){margin-bottom:0;max-width:52ch}

/* ============================ INTEGRATIONS (core + dual marquee) ============================ */
.intg:where(:root.page-brochures,:root.page-brochures *){background:#F3F1EE}
#industries:where(:root.page-brochures,:root.page-brochures *){padding-bottom:0}
.intg-head:where(:root.page-brochures,:root.page-brochures *){margin-bottom:40px;max-width:920px}
.intg-stage:where(:root.page-brochures,:root.page-brochures *){position:relative;border:0;border-radius:24px;background:var(--paper);overflow:hidden;padding:clamp(28px,3.4vw,48px) 0 clamp(18px,2.2vw,30px)}
