.intg-conn .ic-rail:where(:root.page-brochures,:root.page-brochures *){position:absolute;left:0;right:0;top:62%;height:1.5px;background:linear-gradient(90deg,transparent,var(--wine-line) 10%,var(--wine-line) 90%,transparent)}
.intg-conn .ic-pkt:where(:root.page-brochures,:root.page-brochures *){position:absolute;width:7px;height:7px;border-radius:50%;background:var(--wine);box-shadow:0 0 9px 1px rgba(155,27,46,.55)}
