/* ---- NX problem section: normal rhythm, white band (the 140px pair is Contract Verse only) ---- */
html.page-contractverse .nx-prob{padding-top:70px;background:#fff}
html.page-contractverse .nx-prob .sigt-sticky{padding-bottom:0}

/* ---- NX band alternation ---- */
html.page-contractverse .nx-what{background:#fff}
html.page-contractverse .nx-why26{background:#F3F1EE}
html.page-contractverse .nx-does{background:#fff}
html.page-contractverse .nx-pillars{background:#F3F1EE}
html.page-contractverse .nx-ba{background:#fff}

/* ---- why now: closing line small, wine, one line ---- */
html.page-contractverse .nx-whyline{margin:clamp(26px,2.8vw,38px) 0 0;max-width:none;font-size:clamp(14px,1.4vw,17px);line-height:1.4;
  font-weight:600;letter-spacing:-.012em;color:var(--wine);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media(max-width:700px){html.page-contractverse .nx-whyline{white-space:normal}}

/* ---- before / after: paired transition rows ---- */
html.page-contractverse .nx-tr{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;column-gap:clamp(12px,2vw,28px);row-gap:10px}
html.page-contractverse .nx-tr-col{padding-bottom:6px}
html.page-contractverse .nx-tr-tag{font-family:var(--font-mono);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase}
html.page-contractverse .nx-tr-col--b .nx-tr-tag{color:var(--ink-3)}
html.page-contractverse .nx-tr-col--a .nx-tr-tag{color:var(--wine)}
html.page-contractverse .nx-tr-gut{width:clamp(34px,4vw,54px)}
html.page-contractverse .nx-tr-b,html.page-contractverse .nx-tr-a{font-size:15px;line-height:1.5;padding:clamp(14px,1.5vw,18px) clamp(16px,1.8vw,22px);border-radius:14px;text-wrap:pretty}
html.page-contractverse .nx-tr-b{background:var(--paper-2);border:1px dashed var(--line);color:var(--ink-2)}
html.page-contractverse .nx-tr-a{background:#fff;border:1px solid var(--wine-line);color:var(--ink);font-weight:500;box-shadow:0 18px 40px -30px rgba(110,18,28,.4)}
html.page-contractverse .nx-tr-arr{display:grid;place-items:center;width:clamp(34px,4vw,54px);height:34px}
html.page-contractverse .nx-tr-arr svg{width:22px;height:22px;fill:none;stroke:var(--wine);stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;opacity:.5;transition:opacity .3s var(--ease),transform .3s var(--ease)}
html.page-contractverse .nx-tr-b:hover,html.page-contractverse .nx-tr-a:hover{transform:translateY(-2px)}
html.page-contractverse .nx-tr-b,html.page-contractverse .nx-tr-a{transition:transform .3s var(--ease)}
html.page-contractverse .nx-tr-b:hover + .nx-tr-arr svg,html.page-contractverse .nx-tr-arr:hover svg{opacity:1;transform:translateX(3px)}
@media(max-width:760px){
  html.page-contractverse .nx-tr{grid-template-columns:1fr;row-gap:8px}
  html.page-contractverse .nx-tr-gut,html.page-contractverse .nx-tr-col--a,html.page-contractverse .nx-tr-arr{display:none}
  html.page-contractverse .nx-tr-a{margin-bottom:12px}
}

.trustbar:where(:root.page-contact,:root.page-contact *){background:var(--paper);padding-block:70px}
